import{_ as t}from"./chunks/protocol.BCHVaPua.js";import{_ as o,o as d,c as a,a3 as r}from"./chunks/framework.16qmHapV.js";const _=JSON.parse('{"title":"PAI 内容协议","description":"PAI 内容协议 0.1.0-draft.1 的服务发现、发布认证、更新和内容读取接口。","frontmatter":{"title":"PAI 内容协议","description":"PAI 内容协议 0.1.0-draft.1 的服务发现、发布认证、更新和内容读取接口。"},"headers":[],"relativePath":"zh/protocol.md","filePath":"zh/protocol.md"}'),c={name:"zh/protocol.md"};function i(n,e,s,l,p,h){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="pai-内容协议" tabindex="-1">PAI 内容协议 <a class="header-anchor" href="#pai-内容协议" aria-label="Permalink to &quot;PAI 内容协议&quot;">​</a></h1><p>协议版本 <code>0.1.0-draft.1</code> · Profile <code>content</code></p><p>PAI 客户端通过所选服务发布、更新和读取文档。服务端验证上传文件，检查发布权限，保存发布版本，并提供对应内容及原始文件。</p><h2 id="参与者" tabindex="-1">参与者 <a class="header-anchor" href="#参与者" aria-label="Permalink to &quot;参与者&quot;">​</a></h2><ul><li>**宿主应用：**使用 PAI 客户端的 AI 应用或 Harness。</li><li>**客户端：**发现服务能力，发送发布或读取请求。</li><li>**服务端：**在服务中实现内容接口。服务提供者负责账号、凭据、存储和用户界面。</li></ul><p><img src="'+t+'" alt="发布客户端和读取客户端通过同一个 PAI 服务交换内容。"></p><h2 id="http-操作" tabindex="-1">HTTP 操作 <a class="header-anchor" href="#http-操作" aria-label="Permalink to &quot;HTTP 操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>请求目标</th><th>返回内容</th></tr></thead><tbody><tr><td>服务发现</td><td><code>GET /.well-known/pai.json</code></td><td>能力、格式、认证方式和接口地址</td></tr><tr><td>发布</td><td><code>POST endpoints.documents</code></td><td>资源及其发布版本</td></tr><tr><td>更新</td><td><code>PUT resource.updateUrl</code></td><td>新版本或已保存的匹配版本</td></tr><tr><td>资源目录</td><td><code>GET endpoints.resources</code></td><td><code>items</code> 数组中的最新资源信息</td></tr><tr><td>内容读取</td><td><code>GET representations.content</code></td><td><code>resource</code>、<code>document</code>、按顺序排列的 <code>blocks</code> 和 <code>assets</code></td></tr><tr><td>文件下载</td><td><code>GET representations.download</code></td><td>该版本首次保存的原始文件</td></tr></tbody></table><p>客户端使用服务发现和资源响应中返回的地址。发布和更新以完整 <code>.pai</code> 或 <code>.pai.html</code> 文件的原始字节作为请求体。</p><p>写入请求使用 <code>Authorization: Bearer &lt;credential&gt;</code>。服务端根据凭据确定发布者身份。服务发现和已发布内容可公开读取。网络部署使用 HTTPS，本地回环开发服务可使用 HTTP。</p><h2 id="标识与版本" tabindex="-1">标识与版本 <a class="header-anchor" href="#标识与版本" aria-label="Permalink to &quot;标识与版本&quot;">​</a></h2><p><code>document.id</code> 标识不同封装中的同一文档。整数 <code>revision</code> 随内容编辑递增。服务分配资源 ID，发布 <code>version</code> 从 <code>&quot;1&quot;</code> 开始。</p><p>更高的文档修订号产生下一个发布版本。同一修订和内容再次提交时，返回 <code>200</code> 和已保存的版本，历史修订同样适用。同一修订对应不同内容时，返回 <code>409 document_revision_conflict</code>。未曾发布的旧修订返回 <code>409 stale_document_revision</code>。</p><p>返回的每个内容块包含 <code>id</code>、<code>markdown</code> 和 <code>sourceUrl</code>。来源地址指向具体发布版本中的内容块。后续更新保留旧版本的文字、原图和来源地址。客户端下载该版本的文件，再按图片 ID 和声明的封装格式提取图片字节。</p><h2 id="规范与实现" tabindex="-1">规范与实现 <a class="header-anchor" href="#规范与实现" aria-label="Permalink to &quot;规范与实现&quot;">​</a></h2><p><a href="/pai-website/spec/service.html">服务规范</a> · <a href="/pai-website/spec/terminology.html">术语表</a> · <a href="/pai-website/guide/client.html">客户端接入</a> · <a href="/pai-website/guide/server.html">服务端接入</a> · <a href="/pai-website/guide/architecture.html">架构说明</a></p>',16)])])}const P=o(c,[["render",i]]);export{_ as __pageData,P as default};
